    };
}
function d_finish_note(array $p): string {
    $v = (string)$p['variant']; $n = (string)$p['card_name'];
    if (str_contains($n, 'Master Ball Pattern') || str_contains($v, 'Master Ball')) return 'Finish: Master Ball pattern reverse holo, the harder of the two pattern versions to find.';
    if (str_contains($n, 'Poke Ball Pattern') || str_contains($v, 'Poke Ball')) return 'Finish: PokÃ© Ball pattern reverse holo, with PokÃ© Balls printed into the foil.';
    if (preg_match('/Love Ball|Friend Ball|Quick Ball/', $v, $m)) return "Finish: {$m[0]} pattern reverse holo.";
    if (str_contains($n, 'Cosmos Holofoil')) return 'Finish: cosmos holofoil, the stars-and-planets foil seen on many promos.';
    if (str_starts_with($v, 'Reverse Holofoil')) return 'Finish: reverse holo, where the foil sits on the card frame around the picture rather than on the picture itself.';
    if ($v === 'Holofoil' && in_array($p['rarity'], ['Common', 'Uncommon', 'Rare'], true)) return 'Finish: holofoil.';
    return '';
}
function d_secret_note(array $p): string {
    if (preg_match('#^(\d+)/(\d+)$#', (string)$p['card_number'], $m) && (int)$m[1] > (int)$m[2] && $p['rarity'] !== 'Secret Rare')
        return "Note the number: {$p['card_number']} runs past the {$m[2]} cards the set officially lists, which marks it as a secret rare.";
    return '';
}
function d_clean_name(array $p): string {
    $n = trim((string)$p['card_name']);
    $n = trim(preg_replace('/\s*\((Master Ball|Poke Ball) Pattern\)/', '', $n));
    return $n !== '' ? $n : (string)$p['title'];
}
function d_set_link(array $p): string {
    if (empty($p['set_url']) || empty($p['set_name'])) return '';
    return '<a href="' . h($p['set_url']) . '">' . h($p['set_name']) . '</a>';
}
function d_card_page(array $p): string {
    foreach (auto_paths($p) as $path) if (preg_match('#^/cards/(' . implode('|', CARD_NAMES) . ')-pokemon-cards$#', $path, $m))
        return '<a href="' . $path . '">' . ucfirst($m[1]) . ' cards</a>';
    return '';
}
// The priciest singles we carry from the same set (read from the catalog, so it stays accurate).
function d_chase(array $p, int $n = 3): array {
    static $cache = [];
    if (empty($p['set_url'])) return [];
    if (!isset($cache[$p['set_url']])) {
        $cache[$p['set_url']] = all("SELECT id, handle, card_name, title, card_number FROM products WHERE set_url = ? AND section = 'Single Cards' AND published = 1 AND price_usd IS NOT NULL ORDER BY price_usd DESC LIMIT 12", [$p['set_url']]);
    }
    $out = []; $seen = [];
    foreach ($cache[$p['set_url']] as $r) {
        if ((int)$r['id'] === (int)($p['id'] ?? 0)) continue;
        $nm = trim(preg_replace(['/\s*\((Master Ball|Poke Ball) Pattern\)/', '#^\d+\*?/\d+\s+#'], '', $r['card_name'] ?: $r['title']));
        if (isset($seen[$nm]) || $nm === d_clean_name($p)) continue;
        $seen[$nm] = 1;
        $out[] = '<a href="/products/' . h($r['handle']) . '">' . h($nm . ($r['card_number'] ? ' ' . $r['card_number'] : '')) . '</a>';
        if (count($out) >= $n) break;
    }
    return $out;
}
function d_ship(array $p, bool $sealed = false): string {
    return d_pick($p, [
        'Shipping: leaves our warehouse in Japan within two days of payment by EMS, DHL or FedEx with tracking, and typically lands in the US in 3 to 6 working days.',
        'Shipping: tracked EMS, DHL or FedEx from Japan, sent within two days of payment. Orders above $2,000 get Standard shipping free.',
        'Shipping: priced in US dollars and sent from Japan with full tracking (EMS, DHL or FedEx) within two days of your payment clearing.',
    ], 11);
}
function d_lang_note(array $p): string {
    $lang = $p['language'] ?? 'English';
    if ($lang === 'Japanese') return d_pick($p, [
        'Language: Japanese. The card measures the standard 63 x 88 mm, exactly like an English card, so your usual sleeves, toploaders and binder pages fit.',
        'Language: Japanese. Same 63 x 88 mm footprint as English cards, and a print finish plenty of graders prefer.',
        'Language: Japanese. Japanese sets often arrive months ahead of their English counterparts, and the cards are the same size.',
    ], 9);
    if ($lang === 'Chinese') return 'Language: Simplified Chinese, an official print from the PokÃ©mon TCGâ€™s Chinese market, which has become a collecting niche of its own.';
    return d_pick($p, ['Language: English, the version on US store shelves.', 'Language: English. Standard 63 x 88 mm card.'], 9);
}

