/* ------------------------------------------------------------------ products */
function admin_products(): void {
    $where = ['1=1']; $args = [];
    $qq = trim((string)($_GET['q'] ?? ''));
    if ($qq !== '') { foreach (preg_split('/\s+/', mb_strtolower($qq)) as $w) { $where[] = '(LOWER(title) LIKE ? OR LOWER(sku) LIKE ? OR LOWER(handle) LIKE ? OR LOWER(set_name) LIKE ?)'; array_push($args, "%$w%", "%$w%", "%$w%", "%$w%"); } }
    foreach (['game' => 'game', 'section' => 'section', 'lang' => 'language'] as $k => $col) if (!empty($_GET[$k])) { $where[] = "$col = ?"; $args[] = $_GET[$k]; }
    if (($_GET['stock'] ?? '') === '1') $where[] = 'in_stock = 1';
    if (($_GET['stock'] ?? '') === '0') $where[] = 'in_stock = 0';
    if (($_GET['pub'] ?? '') === '0') $where[] = 'published = 0';
    if (($_GET['seo'] ?? '') !== '') { $where[] = 'seo_index = ?'; $args[] = (int)$_GET['seo']; }
    if (($_GET['need'] ?? '') === 'price') $where[] = 'price_usd IS NULL';
    if (($_GET['need'] ?? '') === 'photo') $where[] = "image_url = '' AND image_local = ''";
    if (($_GET['need'] ?? '') === 'featured') $where[] = 'featured > 0';
    $sorts = ['updated' => 'updated_at DESC', 'title' => 'title COLLATE NOCASE', 'price_desc' => 'price_usd IS NULL, price_usd DESC', 'price_asc' => 'price_usd IS NULL, price_usd', 'set' => 'set_name, sort_number', 'new' => 'id DESC'];
    $sort = isset($sorts[$_GET['sort'] ?? '']) ? $_GET['sort'] : 'updated';
    $w = implode(' AND ', $where);
    $total = (int)val("SELECT COUNT(*) FROM products WHERE $w", $args);
    $per = 50; $page = max(1, (int)($_GET['page'] ?? 1)); $pages = max(1, (int)ceil($total / $per));
    $rows = all("SELECT * FROM products WHERE $w ORDER BY {$sorts[$sort]} LIMIT $per OFFSET " . (($page - 1) * $per), $args);
    ob_start(); ?>
<div class="head"><h1>Products <span class="muted">(<?= number_format($total) ?>)</span></h1><a class="btn primary" href="/admin/products/edit">+ Add product</a></div>
