  <select name="seo" aria-label="Google"><option value="">Google: any</option><?= opt(['1' => 'In Google', '0' => 'Not in Google'], (string)($_GET['seo'] ?? ''), true) ?></select>
  <select name="need" aria-label="Needs attention"><option value="">Needs: any</option><?= opt(['price' => 'Needs a price', 'photo' => 'Needs a photo', 'featured' => 'Featured on homepage'], (string)($_GET['need'] ?? ''), true) ?></select>
  <select name="sort" aria-label="Sort"><?= opt(['updated' => 'Recently edited', 'new' => 'Newest', 'title' => 'Name Aâ€“Z', 'price_desc' => 'Price highâ€“low', 'price_asc' => 'Price lowâ€“high', 'set' => 'Set & number'], $sort, true) ?></select>
  <button class="btn">Apply</button><a class="btn ghost" href="/admin/products">Reset</a>
</form>
<form method="post" action="/admin/products/bulk" data-bulk>
