<form method="post" class="edit-grid"><?= csrf_field() ?>
  <div><section class="card">
    <label>Heading on the page (H1)<input name="h1" value="<?= h($c['h1']) ?>"></label>
    <h2>Intro <span class="muted small">(1â€“3 sentences above the products)</span></h2><?= editor('intro', (string)$c['intro'], 4) ?>
    <h2>Text below the products <span class="muted small">(buying guide, FAQ: this is what helps the page rank)</span></h2><?= editor('body', (string)$c['body'], 14) ?>
  </section></div>
  <div><?= seo_fields($c, $c['title'] . ' | Toramori') ?><div class="sticky-save"><button class="btn primary big">Save</button></div></div>
</form>
<?php echo admin_shell('Edit listing page', ob_get_clean(), 'pages');
}

/* ------------------------------------------------------------------ SEO overview, redirects */
function admin_seo(): void {
    $rows = [];
    foreach (all("SELECT path, COALESCE(NULLIF(seo_title,''), title) t, seo_title, meta_desc, primary_kw, seo_index, 'listing' src FROM collections") as $r) $rows[] = $r;
    foreach (all("SELECT path, COALESCE(NULLIF(seo_title,''), title) t, seo_title, meta_desc, primary_kw, seo_index, 'page' src FROM pages WHERE published = 1") as $r) $rows[] = $r;
    $issues = fn($r) => array_filter([$r['seo_title'] === '' ? 'No Google title' : (mb_strlen($r['seo_title']) > 60 ? 'Title too long' : null), $r['meta_desc'] === '' ? 'No description' : (mb_strlen($r['meta_desc']) > 155 ? 'Description too long' : null), $r['primary_kw'] === '' && $r['src'] === 'page' ? 'No keyword' : null]);
    usort($rows, fn($a, $b) => count($issues($b)) <=> count($issues($a)) ?: strcmp($a['path'], $b['path']));
    $prodIdx = (int)val('SELECT COUNT(*) FROM products WHERE published = 1 AND seo_index = 1');
    ob_start(); ?>
<h1>SEO</h1>
<div class="kpis">
  <div class="kpi"><span>Products in Google</span><strong><?= number_format($prodIdx) ?></strong></div>
  <div class="kpi"><span>Pages with issues</span><strong><?= count(array_filter($rows, fn($r) => $issues($r))) ?></strong></div>
  <a class="kpi" href="/sitemap.xml" target="_blank" rel="noopener"><span>Sitemap for Google</span><strong class="small mono">/sitemap.xml â†—</strong></a>
  <a class="kpi" href="/admin/redirects"><span>Redirects</span><strong><?= (int)val('SELECT COUNT(*) FROM redirects') ?></strong></a>
</div>
<div class="card flush"><table class="tbl"><thead><tr><th>Page</th><th>Title in Google</th><th>Chars</th><th>Description</th><th>Issues</th></tr></thead><tbody>
<?php foreach ($rows as $r): $is = $issues($r); $edit = $r['src'] === 'page' ? '/admin/pages/edit?path=' . urlencode($r['path']) : '/admin/collections/edit?path=' . urlencode($r['path']); ?>
<tr><td><a href="<?= h($edit) ?>" class="mono small"><?= h($r['path']) ?></a></td><td class="small"><?= h($r['t']) ?></td><td class="mono small <?= mb_strlen($r['t']) > 60 ? 'amber-text' : '' ?>"><?= mb_strlen($r['t']) ?></td>
<td class="small muted"><?= h(mb_strimwidth($r['meta_desc'], 0, 90, 'â€¦')) ?></td><td><?php foreach ($is as $i): ?><span class="status amber"><?= h($i) ?></span> <?php endforeach ?><?= $is ? '' : '<span class="status green">Good</span>' ?></td></tr>
<?php endforeach ?></tbody></table></div>
<?php echo admin_shell('SEO', ob_get_clean(), 'seo');
}
function admin_redirects(): void {
    if (is_post()) {
        if (!empty($_POST['remove'])) q('DELETE FROM redirects WHERE from_path = ?', [$_POST['remove']]);
        else {
            $from = '/' . trim(parse_url(trim((string)$_POST['from']), PHP_URL_PATH) ?: '', '/'); $to = trim((string)$_POST['to']);
            if ($from !== '/' && $to !== '') q('INSERT OR REPLACE INTO redirects(from_path, to_path, code) VALUES(?, ?, 301)', [$from, $to]);
        }
        flash('Redirects updated.'); redirect('/admin/redirects');
    }
