        <p><?= h(setting('other_payment_note')) ?></p>
        <p class="small muted">We will use <?= h($o['email']) ?><?= $o['phone'] ? ' and ' . h($o['phone']) : '' ?>. Check that payment details come from <?= h(setting('support_email')) ?> and quote your order number <span class="mono"><?= h($o['code']) ?></span>.</p>
      <?php endif ?>
    </section>
    <section class="panel-box">
