function view_sets(array $__vars): void { extract($__vars, EXTR_SKIP); ?><?php
$groups = [];
foreach ($sets as $s) {
    $g = $s['game'] === 'PokÃ©mon' ? ($s['series'] ?: 'Japanese & special sets') : $s['game'];
    $groups[$g][] = $s;
}
uksort($groups, function ($a, $b) {
    $o = ['Mega Evolution' => 1, 'Scarlet & Violet' => 2, 'Japanese & special sets' => 3, 'Sword & Shield' => 4];
    return ($o[$a] ?? 10) <=> ($o[$b] ?? 10) ?: strcmp($a, $b);
});
?>
<div class="wrap">
  <nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>Sets</span></nav>
  <h1 class="h1"><?= h($h1) ?></h1>
  <?php if ($intro): ?><div class="intro prose"><?= $intro ?></div><?php else: ?><p class="lead muted">All the Japanese and English PokÃ©mon sets we carry, newest series and releases at the top, followed by our other games. Open a set for its numbered checklist with prices and its sealed boxes.</p><?php endif ?>
  <label class="sr" for="setfilter">Find a set</label>
  <input id="setfilter" class="input setfilter" type="search" placeholder="Find a set, e.g. Prismatic" data-setfilter>
  <?php foreach ($groups as $g => $list): ?>
  <section class="section-sm" data-setgroup>
    <h2 class="eyebrow gold"><?= h($g) ?></h2>
    <div class="setlist">
      <?php foreach ($list as $s): ?><a href="<?= h($s['path']) ?>" data-name="<?= h(mb_strtolower($s['title'])) ?>"><span class="flex1"><?= h($s['title']) ?></span><span class="mono small muted"><?= number_format((int)$s['instock']) ?> in stock Â· <?= number_format((int)$s['n']) ?> â†’</span></a><?php endforeach ?>
    </div>
  </section>
  <?php endforeach ?>
</div>
<?php }

